$pdo=db();$canManage=in_array($user['role'],['Administrator','Head'],true);$canCapture=in_array($user['role'],['Administrator','Head','Clerk'],true);$new=isset($_GET['new']);$sessionId=filter_var($_GET['session']??null,FILTER_VALIDATE_INT);$candidateId=filter_var($_GET['candidate']??null,FILTER_VALIDATE_INT);$sessions=[];$subjects=[];$candidates=[];$entrySubjects=[];$candidate=null;$selectedSession=null;
try{$sessions=$pdo->query("SELECT es.*,(SELECT COUNT(*) FROM exam_candidates ec WHERE ec.session_id=es.id) AS candidate_count,(SELECT COUNT(*) FROM exam_candidates ec WHERE ec.session_id=es.id AND ec.status='Submitted') AS submitted_count FROM exam_sessions es ORDER BY es.exam_year DESC,es.session_name,es.level")->fetchAll();$subjects=$pdo->query("SELECT id,subject_code,subject_name,level FROM subjects WHERE active=1 ORDER BY subject_name")->fetchAll();if($sessionId){foreach($sessions as $s)if((int)$s['id']===$sessionId)$selectedSession=$s;if($selectedSession){$q=$pdo->prepare('SELECT ec.*,s.admission_no,s.form_level,s.stream FROM exam_candidates ec JOIN students s ON s.id=ec.student_id WHERE ec.session_id=:session ORDER BY ec.status,ec.surname_snapshot,ec.first_names_snapshot');$q->execute(['session'=>$sessionId]);$candidates=$q->fetchAll();$q=$pdo->prepare('SELECT ess.subject_id,ess.option_group,s.subject_code,s.subject_name FROM exam_session_subjects ess JOIN subjects s ON s.id=ess.subject_id WHERE ess.session_id=:id ORDER BY s.subject_name');$q->execute(['id'=>$sessionId]);$entrySubjects=$q->fetchAll();}}if($candidateId){$q=$pdo->prepare('SELECT ec.*,s.admission_no,s.form_level,s.stream,es.level,es.exam_year,es.session_name,es.status AS session_status,es.id AS session_id,es.opens_on,es.entry_deadline FROM exam_candidates ec JOIN students s ON s.id=ec.student_id JOIN exam_sessions es ON es.id=ec.session_id WHERE ec.id=:id');$q->execute(['id'=>$candidateId]);$candidate=$q->fetch()?:null;if($candidate){$sessionId=(int)$candidate['session_id'];$selectedSession=null;foreach($sessions as $s)if((int)$s['id']===$sessionId)$selectedSession=$s;$q=$pdo->prepare('SELECT ess.subject_id,ess.option_group,s.subject_code,s.subject_name FROM exam_session_subjects ess JOIN subjects s ON s.id=ess.subject_id WHERE ess.session_id=:id ORDER BY s.subject_name');$q->execute(['id'=>$sessionId]);$entrySubjects=$q->fetchAll();$q=$pdo->prepare('SELECT ec.*,s.admission_no,s.form_level,s.stream FROM exam_candidates ec JOIN students s ON s.id=ec.student_id WHERE ec.session_id=:session ORDER BY ec.status,ec.surname_snapshot,ec.first_names_snapshot');$q->execute(['session'=>$sessionId]);$candidates=$q->fetchAll();$q=$pdo->prepare('SELECT cs.*,s.subject_code,s.subject_name FROM exam_candidate_subjects cs JOIN subjects s ON s.id=cs.subject_id WHERE cs.candidate_id=:id ORDER BY s.subject_name');$q->execute(['id'=>$candidateId]);$candidateSubjects=$q->fetchAll();}}if($canCapture){$students=$pdo->query("SELECT id,admission_no,first_name,last_name,form_level,stream FROM students WHERE status='Active' ORDER BY form_level,stream,last_name,first_name LIMIT 3000")->fetchAll();}}catch(Throwable $e){error_log('Exams page failed: '.$e->getMessage());echo '<section class="panel settings-panel"><h1>ZIMSEC entries setup required</h1><p>An administrator should import <code>database/migrations/014_zimsec_entries.sql</code> into the school database, then reload this page.</p></section>';return;}
$today=date('Y-m-d');$candidateSubjects=$candidateSubjects??[];$candidateSubjectMap=[];foreach($candidateSubjects as $cs)$candidateSubjectMap[(int)$cs['subject_id']]=$cs;
