['level']) ?></td><td><input name="option_groups[<?= (int)$s['id'] ?>]" maxlength="40" placeholder="e.g. LANGUAGES"></td></tr><?php endforeach; ?></tbody></table></div><p class="privacy-note">Use only the subject offerings and entry rules confirmed for your centre in the official ZIMSEC system.</p><div class="form-actions"><a class="outline-button" href="?page=exams">Cancel</a><button class="primary-button">Create session</button></div></form></section><?php endif; ?>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>Examination sessions</h2><p>Select a session to manage its local candidate register.</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Year / session</th><th>Level / entry type</th><th>Centre number</th><th>Entry window</th><th>Entries</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($sessions as $s): ?><tr><td><b><?= (int)$s['exam_year'] ?> · <?= h($s['session_name']) ?></b></td><td><?= h($s['level']) ?><br><span class="muted-cell"><?= h($s['entry_type']) ?></span></td><td><?= h($s['centre_number']) ?></td><td><?= h(date('d M Y',strtotime($s['opens_on']))) ?> – <?= h(date('d M Y',strtotime($s['entry_deadline']))) ?></td><td><?= (int)$s['candidate_count'] ?> total / <?= (int)$s['submitted_count'] ?> submitted</td><td><span class="status-pill"><?= h($s['status']) ?></span></td><td><a class="outline-button compact-button" href="?page=exams&session=<?= (int)$s['id'] ?>">Open register</a><?php if($canManage&&$s['status']==='Draft'&&$today>=$s['opens_on']&&$today<=$s['entry_deadline']): ?><form method="post" action="actions/exam_session_status.php" class="inline-action-form"><?= csrf_field() ?><input type="hidden" name="session_id" value="<?= (int)$s['id'] ?>"><input type="hidden" name="status" value="Open"><button class="text-button">Open entries</button></form><?php elseif($canManage&&$s['status']==='Open'): ?><form method="post" action="actions/exam_session_status.php" class="inline-action-form" onsubmit="return confirm('Close this examination entry window?')"><?= csrf_field() ?><input type="hidden" name="session_id" value="<?= (int)$s['id'] ?>"><input type="hidden" name="status" value="Closed"><button class="text-button">Close entries</button></form><?php endif; ?></td></tr><?php endforeach; if(!$sessions): ?><tr><td colspan="7" class="empty-cell">No exam sessions yet. Create one using the dates and subjects provided by your centre’s ZIMSEC arrangements.</td></tr><?php endif; ?></tbody></table></div></section>
<?php if($selectedSession): ?><section class="panel learners-panel"><div class="panel-heading"><div><h2><?= (int)$selectedSession['exam_year'] ?> <?= h($selectedSession['session_name']) ?> · <?= h($selectedSession['level']) ?></h2><p>Centre <?= h($selectedSession['centre_number']) ?> · <?= (int)$selectedSession['candidate_count'] ?> candidates · status <?= h($selectedSession['status']) ?></p></div><?php if($canCapture): ?><a class="outline-button" href="actions/exam_register_export.php?session_id=<?= (int)$selectedSession['id'] ?>">Download review CSV</a><?php endif; ?></div>
<?php if($canCapture&&$selectedSession['status']==='Open'&&$today>=$selectedSession['opens_on']&&$today<=$selectedSession['entry_deadline']): ?><form method="post" action="actions/exam_candidate_save.php" class="inline-form fee-schedule-form"><?= csrf_field() ?><input type="hidden" name="session_id" value="<?= (int)$selectedSession['id'] ?>"><label>Learner<select name="student_id" required><option value="">Select active learner</option><?php foreach($students as $st): ?><option value="<?= (int)$st['id'] ?>"><?= h('Form '.$st['form_level'].($st['stream']?' '.$st['stream']:'').' · '.$st['first_name'].' '.$st['last_name'].' ('.$st['admission_no'].')') ?></option><?php endforeach; ?></select></label><label>Candidate type<select name="candidate_type"><option>Formal</option><option>Nonformal</option></select></label><label>Payment type<select name="payment_type"><option>Self</option><option>BEAM</option></select></label><label>Nationality<select name="nationality"><option>Local</option><option>Territorial</option></select></label><fieldset class="full-width"><legend>Special requirements <span class="optional">Select if applicable</span></legend><?php foreach(['Hearing','Physical','Visual'] as $req): ?><label class="checkbox-label"><input type="checkbox" name="special_requirements[]" value="<?= h($req) ?>"> <?= h($req) ?> impairment</label><?php endforeach; ?></fieldset><label class="checkbox-label full-width"><input type="checkbox" name="confirm_cross_level" value="1"> I checked the timetable and confirm this candidate needs entries at another level in the same sitting, if applicable.</label><button class="primary-button">Add candidate draft</button></form><?php elseif($selectedSession['status']!=='Open'): ?><p class="privacy-note">This session is not open for new entries.</p><?php endif; ?>
<div class="table-scroll"><table class="data-table"><thead><tr><th>Candidate</th><th>Class</th><th>Candidate type / payment</th><th>Subjects</th><th>ZIMSEC candidate no.</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($candidates as $c): $subjectCountQuery=$pdo->prepare('SELECT COUNT(*) FROM exam_candidate_subjects WHERE candidate_id=:id');$subjectCountQuery->execute(['id'=>$c['id']]);$subjectCount=(int)$subjectCountQuery->fetchColumn(); ?><tr><td><b><?= h($c['surname_snapshot'].', '.$c['first_names_snapshot']) ?></b><br><span class="muted-cell"><?= h($c['admission_no']) ?> · DOB <?= $c['date_of_birth_snapshot']?h(date('d M Y',strtotime($c['date_of_birth_snapshot']))):'not recorded' ?></span></td><td>Form <?= (int)$c['form_level'] ?><?= $c['stream']?' · '.h($c['stream']):'' ?></td><td><?= h($c['candidate_type']) ?> · <?= h($c['payment_type']) ?> · <?= h($c['nationality']) ?><?php if($c['special_requirements']): ?><br><span class="muted-cell">Requirements: <?= h(str_replace(',',' · ',$c['special_requirements'])) ?></span><?php endif; ?></td><td><?= $subjectCount ?><?php if($subjectCount): ?><br><a class="text-button" href="?page=exams&candidate=<?= (int)$c['id'] ?>">View / edit subjects</a><?php endif; ?></td><td><?= h($c['candidate_number']?:'Not yet assigned') ?></td><td><span class="status-pill"><?= h($c['status']) ?></span><?php if($c['withdrawal_reason']): ?><br><span class="muted-cell">Reason: <?= h($c['withdrawal_reason']) ?></span><?php endif; ?></td><td><?php if($canCapture&&$c['status']==='Draft'): ?><a class="outline-button compact-button" href="?page=exams&candidate=<?= (int)$c['id'] ?>">Subjects</a><?php endif; ?><?php if($canManage&&$c['status']==='Draft'&&$subjectCount>0): ?><form method="post" action="actions/exam_candidate_submit.php" onsubmit="return confirm('Mark this completed candidate entry as submitted in the school register? This does not send it to ZIMSEC.')"><?= csrf_field() ?><input type="hidden" name="candidate_id" value="<?= (int)$c['id'] ?>"><button class="text-button">Mark school copy submitted</button></form><?php endif; ?><?php if($canManage&&$c['status']==='Submitted'&&!$c['candidate_number']): ?><form method="post" action="actions/exam_candidate_admin.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="operation" value="candidate_number"><input type="hidden" name="record_id" value="<?= (int)$c['id'] ?>"><label>Record assigned candidate no.<input name="candidate_number" maxlength="24" required></label><button class="outline-button compact-button">Save number</button></form><?php endif; ?><?php if($canManage&&in_array($c['status'],['Draft','Submitted'],true)): ?><details><summary>Withdraw entry</summary><form method="post" action="actions/exam_candidate_admin.php" class="compact-form" onsubmit="return confirm('Record this candidate as withdrawn from this examination entry?')"><?= csrf_field() ?><input type="hidden" name="operation" value="withdraw"><input type="hidden" name="record_id" value="<?= (int)$c['id'] ?>"><label>Reason<input name="reason" required minlength="5" maxlength="255"></label><button class="outline-button">Confirm withdrawal</button></form></details><?php endif; ?><?php if($canManage&&$c['status']==='Withdrawn'): ?><a class="text-button" href="?page=exams&candidate=<?= (int)$c['id'] ?>">Review withdrawn entry</a><?php endif; ?></td></tr><?php endforeach; if(!$candidates): ?><tr><td colspan="7" class="empty-cell">No candidates are recorded for this session.</td></tr><?php endif; ?></tbody></table></div></section><?php endif; ?>
