<section class="panel settings-panel"><div class="panel-heading"><div><h2>Subject entries · <?= h($candidate['surname_snapshot'].', '.$candidate['first_names_snapshot']) ?></h2><p><?= h($candidate['session_name']) ?> <?= (int)$candidate['exam_year'] ?> · <?= h($candidate['level']) ?> · candidate entry <?= h($candidate['status']) ?></p></div><a class="outline-button" href="?page=exams&session=<?= (int)$candidate['session_id'] ?>">Back to candidate register</a></div><?php if($canCapture&&$candidate['status']==='Draft'&&$candidate['session_status']==='Open'&&$today>=$candidate['opens_on']&&$today<=$candidate['entry_deadline']): ?><form method="post" action="actions/exam_subjects_save.php"><?= csrf_field() ?><input type="hidden" name="candidate_id" value="<?= (int)$candidate['id'] ?>"><p>Select the subjects the candidate is sitting. O-Level entries are limited to nine subjects. For each repeat subject, provide previous year, centre and candidate number.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Enter</th><th>Subject</th><th>Option group</th><th>Repeat sitting</th><th>Previous sitting details</th></tr></thead><tbody><?php foreach($entrySubjects as $subject): $old=$candidateSubjectMap[(int)$subject['subject_id']]??null; ?><tr><td><input type="checkbox" name="subject_ids[]" value="<?= (int)$subject['subject_id'] ?>" <?= $old?'checked':'' ?>></td><td><?= h($subject['subject_name']) ?> (<?= h($subject['subject_code']) ?>)</td><td><?= h($subject['option_group']?:'—') ?></td><td><label class="checkbox-label"><input type="checkbox" name="repeat[<?= (int)$subject['subject_id'] ?>][is_repeat]" value="1" <?= $old&&$old['is_repeat']?'checked':'' ?>> Repeat</label></td><td><div class="form-grid"><label>Previous year<input type="number" name="repeat[<?= (int)$subject['subject_id'] ?>][previous_year]" min="1990" max="<?= (int)$candidate['exam_year']-1 ?>" value="<?= h($old['previous_year']??'') ?>"></label><label>Previous centre no.<input name="repeat[<?= (int)$subject['subject_id'] ?>][previous_centre_number]" maxlength="30" value="<?= h($old['previous_centre_number']??'') ?>"></label><label>Previous candidate no.<input name="repeat[<?= (int)$subject['subject_id'] ?>][previous_candidate_number]" maxlength="24" value="<?= h($old['previous_candidate_number']??'') ?>"></label></div></td></tr><?php endforeach; if(!$entrySubjects): ?><tr><td colspan="5" class="empty-cell">No subjects are configured for this session. The session manager must configure offerings first.</td></tr><?php endif; ?></tbody></table></div><button class="primary-button">Save draft subjects</button></form><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Subject</th><th>Entry</th><th>Previous sitting</th></tr></thead><tbody><?php foreach($candidateSubjects as $subject): ?><tr><td><?= h($subject['subject_name']) ?> (<?= h($subject['subject_code']) ?>)</td><td><?= $subject['is_repeat']?'Repeat':'First sitting' ?></td><td><?= $subject['is_repeat']?h($subject['previous_year'].' · Centre '.$subject['previous_centre_number'].' · Candidate '.$subject['previous_candidate_number']):'—' ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php elseif($candidateId): ?><div class="alert alert-warn">Candidate entry was not found.</div><?php endif; ?>
<script>const level=document.getElementById('examLevel');function filterExamSubjects(){if(!level)return;document.querySelectorAll('.exam-subject-option').forEach(function(row){row.hidden=row.dataset.level!=='Both'&&row.dataset.level!==level.value});}level?.addEventListener('change',filterExamSubjects);filterExamSubjects();</script>
